package md0

// documentCSS is the single visual language for every md0 document surface.
// Static renders, snapshots, and the live viewer all consume this stylesheet.
// Viewer chrome (settings, export actions, runtime errors) lives separately in
// browser.go so document presentation never depends on the browser shell.
const documentCSS = `
:root{--md0-font-serif:Charter,"Iowan Old Style","Palatino Linotype",Palatino,"Book Antiqua",Georgia,serif;--md0-font-sans:"Avenir Next",Avenir,"SF Pro Text","SF Pro Display",system-ui,-apple-system,BlinkMacSystemFont,"Helvetica Neue",sans-serif;--md0-font-mono:"SFMono-Regular",Menlo,Consolas,"Liberation Mono",monospace;--md0-document-font:var(--md0-font-serif);--md0-font-size:17px;--md0-measure:790px;--md0-row-y:8px;--paper:#fff;--card:#fff;--ink:#171717;--muted:#70706c;--faint:#979791;--line:#e4e4e1;--surface:#f7f7f5;--surface-hover:#f1f1ee;--surface-pressed:#e9e9e5;--field:#fff;--field-border:#d8d8d4;--field-hover:#b9b9b3;--green:#247447;--red:#a83d3d;--focus:#5d6fe5;--focus-soft:color-mix(in srgb,var(--focus) 18%,transparent);--chart-0:#20201f;--chart-1:#5a5a56;--chart-2:#96968f;--chart-3:#c6c6bf;color-scheme:light}
:root[data-md0-theme="light"]{--paper:#fff;--card:#fff;--ink:#171717;--muted:#70706c;--faint:#979791;--line:#e4e4e1;--surface:#f7f7f5;--surface-hover:#f1f1ee;--surface-pressed:#e9e9e5;--field:#fff;--field-border:#d8d8d4;--field-hover:#b9b9b3;--green:#247447;--red:#a83d3d;--focus:#5d6fe5;--focus-soft:color-mix(in srgb,var(--focus) 18%,transparent);--chart-0:#20201f;--chart-1:#5a5a56;--chart-2:#96968f;--chart-3:#c6c6bf;color-scheme:light}
:root[data-md0-theme="dark"]{--paper:#17181b;--card:#17181b;--ink:#e9e9e5;--muted:#a7a69f;--faint:#7e7f7a;--line:#35383d;--surface:#202226;--surface-hover:#282a30;--surface-pressed:#30333a;--field:#1d1f23;--field-border:#41444b;--field-hover:#5a5e67;--green:#82c99a;--red:#f09191;--focus:#9ba8ff;--focus-soft:color-mix(in srgb,var(--focus) 20%,transparent);--chart-0:#e9e9e5;--chart-1:#b8b8b1;--chart-2:#85857f;--chart-3:#60615d;color-scheme:dark}
@media(prefers-color-scheme:dark){:root:not([data-md0-theme="light"]):not([data-md0-theme="dark"]){--paper:#17181b;--card:#17181b;--ink:#e9e9e5;--muted:#a7a69f;--faint:#7e7f7a;--line:#35383d;--surface:#202226;--surface-hover:#282a30;--surface-pressed:#30333a;--field:#1d1f23;--field-border:#41444b;--field-hover:#5a5e67;--green:#82c99a;--red:#f09191;--focus:#9ba8ff;--focus-soft:color-mix(in srgb,var(--focus) 20%,transparent);--chart-0:#e9e9e5;--chart-1:#b8b8b1;--chart-2:#85857f;--chart-3:#60615d;color-scheme:dark}}
:root[data-md0-font="sans"]{--md0-document-font:var(--md0-font-sans)}:root[data-md0-font="mono"]{--md0-document-font:var(--md0-font-mono)}
:root[data-md0-density="comfortable"]{--md0-row-y:13px}:root[data-md0-text-size="small"]{--md0-font-size:15px}:root[data-md0-text-size="large"]{--md0-font-size:19px}:root[data-md0-width="narrow"]{--md0-measure:650px}:root[data-md0-width="wide"]{--md0-measure:1020px}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--md0-document-font);font-size:var(--md0-font-size);line-height:1.58;-webkit-font-smoothing:antialiased;transition:background-color .14s ease,color .14s ease}#md0-document{max-width:var(--md0-measure);margin:44px auto;padding:0 24px 72px}.md0-region{display:block}.md0-doc h1,.md0-doc h2,.md0-doc h3{font-family:var(--md0-document-font);letter-spacing:-.018em}.md0-doc h1{font-size:2.3rem;line-height:1.08;margin:0 0 14px;padding-bottom:10px;border-bottom:1px solid var(--line)}.md0-doc h2{font-size:1.48rem;line-height:1.2;margin:27px 0 9px;padding-bottom:5px;border-bottom:1px solid var(--line)}.md0-doc p{margin:.62em 0}.md0-doc code,.md0-chart-title,.md0-table-title{font-family:var(--md0-font-mono)}
.md0-input{display:grid;grid-template-columns:minmax(180px,1fr) minmax(220px,290px) auto;gap:18px;align-items:center;margin:0;padding:var(--md0-row-y) 0;border:0;border-bottom:1px solid var(--line);border-radius:0;background:transparent;box-shadow:none}.md0-input:first-of-type{border-top:1px solid var(--line)}.md0-input>span:first-child{min-width:0;font-weight:500}.md0-input>input:not([type="checkbox"]){justify-self:stretch;width:100%;height:42px;padding:0 12px;border:1px solid var(--field-border);border-radius:10px;background:var(--field);color:var(--ink);font-family:var(--md0-font-sans);font-size:.93rem;font-variant-numeric:tabular-nums;outline:0;transition:border-color .12s ease,box-shadow .12s ease}.md0-input>input:not([type="checkbox"]):hover{border-color:var(--field-hover)}.md0-input>input:not([type="checkbox"]):focus-visible{border-color:var(--focus);box-shadow:0 0 0 3px var(--focus-soft)}.md0-input>input[type=number]{-moz-appearance:textfield;appearance:textfield}.md0-input>input[type=number]::-webkit-inner-spin-button,.md0-input>input[type=number]::-webkit-outer-spin-button{-webkit-appearance:none;appearance:none;margin:0}.md0-input>input[type="checkbox"]{justify-self:end;width:20px;height:20px;margin:0;accent-color:var(--ink)}.md0-input>small{justify-self:end;color:var(--muted);font:600 .7rem/1 var(--md0-font-sans);letter-spacing:.01em}.md0-control{min-width:0;display:flex;align-items:stretch;height:42px;border:1px solid var(--field-border);border-radius:10px;background:var(--field);overflow:hidden;transition:border-color .12s ease,box-shadow .12s ease,background .12s ease}.md0-control:hover{border-color:var(--field-hover)}.md0-control:focus-within{border-color:var(--focus);box-shadow:0 0 0 3px var(--focus-soft)}.md0-control input{min-width:0;width:100%;border:0!important;outline:0!important;box-shadow:none!important;background:transparent!important;color:var(--ink);padding:0 12px;font-family:var(--md0-font-sans);font-size:.93rem;font-variant-numeric:tabular-nums}.md0-control input[type=number]{-moz-appearance:textfield;appearance:textfield}.md0-control input[type=number]::-webkit-inner-spin-button,.md0-control input[type=number]::-webkit-outer-spin-button{-webkit-appearance:none;appearance:none;margin:0}.md0-unit{display:flex;align-items:center;flex:0 0 auto;padding:0 10px;color:var(--muted);border-left:1px solid var(--line);background:color-mix(in srgb,var(--surface) 55%,var(--field));font:600 .7rem/1 var(--md0-font-sans);letter-spacing:.01em;user-select:none}.md0-unit.percent{font-size:.86rem;padding-inline:11px}.md0-stepper{flex:0 0 31px;display:grid;grid-template-rows:1fr 1fr;border-left:1px solid var(--line);background:var(--surface)}.md0-step{display:grid;place-items:center;border:0;padding:0;background:transparent;color:var(--muted);font:700 12px/1 var(--md0-font-sans);cursor:pointer;transition:background .1s,color .1s}.md0-step:first-child{border-bottom:1px solid var(--line)}.md0-step:hover{background:var(--surface-hover);color:var(--ink)}.md0-step:active{background:var(--surface-pressed);transform:translateY(.5px)}.md0-step:focus-visible{outline:2px solid var(--focus);outline-offset:-2px}.md0-switch-shell{justify-self:end;position:relative;width:44px;height:26px}.md0-switch-shell input{position:absolute;inset:0;width:44px!important;height:26px!important;margin:0;opacity:0;cursor:pointer;z-index:2}.md0-switch-visual{display:block;width:44px;height:26px;border-radius:999px;background:var(--surface-pressed);transition:background .15s ease;box-shadow:inset 0 0 0 1px var(--field-border)}.md0-switch-visual:after{content:"";display:block;width:20px;height:20px;margin:3px;border-radius:50%;background:var(--paper);box-shadow:0 1px 3px rgba(0,0,0,.22);transition:transform .16s ease}.md0-switch-shell input:checked+.md0-switch-visual{background:var(--ink)}.md0-switch-shell input:checked+.md0-switch-visual:after{transform:translateX(18px)}.md0-switch-shell input:focus-visible+.md0-switch-visual{outline:2px solid var(--focus);outline-offset:2px}.md0-switch-shell+small{display:none}.md0-input input[aria-invalid="true"]{box-shadow:inset 0 0 0 1px var(--red)!important}.md0-control:has(input[aria-invalid="true"]){border-color:var(--red);box-shadow:0 0 0 3px color-mix(in srgb,var(--red) 16%,transparent)}
.md0-show{margin:12px 0;padding:7px 10px;border:0;border-left:2px solid var(--line);border-radius:0;background:transparent}.md0-assert{margin:17px 0;padding:9px 0 9px 12px;border:0;border-left:2px solid;border-radius:0;background:transparent}.md0-assert.pass{background:transparent;border-color:var(--green);color:var(--green)}.md0-assert.fail{background:transparent;border-color:var(--red);color:var(--red)}.md0-assert-title{font-family:var(--md0-font-sans);font-weight:700;text-transform:uppercase;letter-spacing:.07em;font-size:.68rem}.md0-assert code{display:block;margin-top:4px;color:inherit}.md0-assert-message p{margin:.4rem 0 0}
.md0-chart,.md0-table{margin:22px 0;padding:0;border:0;border-radius:0;background:transparent;box-shadow:none}.md0-chart-title,.md0-table-title{font-size:.72rem;color:var(--muted);margin:0 0 10px}.md0-chart svg{display:block;width:100%;height:auto}.md0-chart .axis{stroke:var(--line);stroke-width:1}.md0-chart .zero-axis{stroke:var(--muted)}.md0-chart .bar{transition:opacity .12s ease}.md0-chart .bar:hover{opacity:.78}.md0-chart .bar-0{fill:var(--chart-0)}.md0-chart .bar-1{fill:var(--chart-1)}.md0-chart .bar-2{fill:var(--chart-2)}.md0-chart .bar-3{fill:var(--chart-3)}.md0-chart .bar.negative{opacity:.7}.md0-chart text{font-family:var(--md0-font-sans);fill:var(--muted);font-size:13px}.md0-chart .value{fill:var(--ink);font-weight:650;font-variant-numeric:tabular-nums}.md0-table-scroll{overflow-x:auto}.md0-table table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}.md0-table th,.md0-table td{text-align:left;padding:7px 4px;border-bottom:1px solid var(--line);white-space:nowrap}.md0-table th{font-family:var(--md0-font-sans);font-weight:700;color:var(--muted);font-size:.75rem;letter-spacing:.015em}.md0-table tbody tr{transition:background .1s}.md0-table tbody tr:hover{background:color-mix(in srgb,var(--surface) 62%,transparent)}.md0-table tbody tr:last-child td{border-bottom:1px solid var(--ink)}.md0-table th:last-child,.md0-table td:last-child{text-align:right}.md0-sr-only{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}pre{overflow:auto;padding:12px;border:1px solid var(--line);border-radius:4px;background:var(--surface)}pre code{white-space:pre}code{font-size:.9em}strong{font-weight:700}
@media(max-width:640px){#md0-document{margin:28px auto;padding:0 18px 48px}.md0-doc h1{font-size:1.95rem}.md0-input{grid-template-columns:1fr;gap:6px;padding:10px 0}.md0-control{height:44px}.md0-switch-shell{justify-self:start}.md0-input>small{justify-self:start}}
`
